  --hairline:#334155; --hairline-2:#273244; --zebra:#243044;
  --brand:#34d399; --verify:#60a5fa;
  --intake:#94a3b8; --review:#fbbf24; --audit:#a78bfa; --done:#34d399;
  --shadow:0 1px 2px #0006, 0 14px 34px -18px #000a;
  --radius:14px;
}
* { box-sizing:border-box; }
html, body { margin:0; padding:0; background:transparent; }
body {
  color:var(--ink);
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  font-size:14px; line-height:1.5; -webkit-font-smoothing:antialiased;
}
.wrap { display:flex; flex-direction:column; gap:18px; padding:2px; }
.tnum { font-variant-numeric:tabular-nums; }

/* KPI tiles */
.kpis { display:grid; grid-template-columns:repeat(3,1fr); gap:14px; }
.tile { background:var(--tile); border:1px solid var(--hairline); border-radius:var(--radius); padding:16px; box-shadow:var(--shadow); position:relative; overflow:hidden; }
.tile::before { content:""; position:absolute; left:0; top:0; bottom:0; width:3px; background:var(--accent,var(--brand)); }
.tile .lab { font-size:12px; color:var(--muted); font-weight:600; }
.tile .val { font-size:30px; font-weight:700; letter-spacing:-.02em; margin:6px 0 2px; line-height:1; }
.tile .val small { font-size:18px; font-weight:600; }
.tile .meta { font-size:12px; color:var(--muted); }
.barline { height:5px; border-radius:3px; background:var(--hairline-2); overflow:hidden; margin-top:11px; }
.barline > i { display:block; height:100%; border-radius:3px; background:var(--accent,var(--brand)); }

/* Panels */
.panel { background:var(--surface); border:1px solid var(--hairline); border-radius:var(--radius); box-shadow:var(--shadow); }
.panel-head { display:flex; align-items:baseline; justify-content:space-between; gap:12px; padding:17px 20px; border-bottom:1px solid var(--hairline-2); }
.panel-head h2 { margin:0; font-size:15px; font-weight:700; letter-spacing:-.01em; }
.panel-head .hint { font-size:12.5px; color:var(--muted); }
