.legend { display:flex; flex-wrap:wrap; gap:14px 18px; padding:14px 20px 4px; }
.legend span { display:inline-flex; align-items:center; gap:7px; font-size:12px; color:var(--muted); font-weight:600; }
.legend span::before { content:""; width:10px; height:10px; border-radius:3px; background:var(--c); }
.stage { display:grid; grid-template-columns:168px 1fr 92px; align-items:center; gap:14px; padding:9px 0; }
.stage + .stage { border-top:1px solid var(--hairline-2); }
.stage .name { font-size:13px; font-weight:600; display:flex; align-items:center; gap:9px; }
.stage .name i { width:9px; height:9px; border-radius:3px; background:var(--c); flex:none; }
