.track > b { display:block; height:100%; border-radius:6px; background:var(--c); min-width:3px; }
.stage .num { text-align:right; font-weight:700; font-size:15px; letter-spacing:-.01em; }
.stage .num small { display:block; font-weight:600; font-size:11px; color:var(--muted); }
.stage.empty .num { color:var(--ink-soft); }

