.tablescroll { overflow-x:auto; padding:4px 6px 6px; }
.tablescroll::-webkit-scrollbar { height:9px; }
.tablescroll::-webkit-scrollbar-track { background:transparent; }
.tablescroll::-webkit-scrollbar-thumb { background:var(--hairline); border-radius:5px; border:2px solid var(--surface); }
.tablescroll { scrollbar-width:thin; scrollbar-color:var(--hairline) transparent; }
table.matrix { width:100%; border-collapse:collapse; min-width:720px; }
table.matrix th, table.matrix td { padding:12px 10px; text-align:right; white-space:nowrap; }
table.matrix thead th { font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); border-bottom:1px solid var(--hairline); }
table.matrix th.rowlab, table.matrix td.rowlab { text-align:left; font-weight:600; color:var(--ink); }
table.matrix tbody td { font-variant-numeric:tabular-nums; border-bottom:1px solid var(--hairline-2); }
table.matrix tbody tr:hover { background:var(--zebra); }
table.matrix td .v { font-weight:600; }
table.matrix td.zero .v { color:var(--ink-soft); font-weight:500; }
table.matrix td.total .v { color:var(--ink); font-weight:700; }
table.matrix td.proc .v { color:var(--done); }
table.matrix tr.alltime td { border-top:1px solid var(--hairline); font-weight:700; }
table.matrix tr.alltime td.rowlab { color:var(--ink); }
.col-div { border-left:1px solid var(--hairline); }

@media (max-width:720px) {
  .kpis { grid-template-columns:1fr; }
  .stage { grid-template-columns:120px 1fr 70px; }
}


/* clickable drill cells — blue links */
table.matrix td.clk { cursor: pointer; }
table.matrix td.clk .v { color: var(--verify); }
table.matrix td.clk.zero .v { color: var(--verify); opacity: .55; }
table.matrix td.clk:hover { background: var(--zebra); }
table.matrix td.clk:hover .v { text-decoration: underline; }
.stage.clk { cursor: pointer; border-radius: 8px; }
.stage.clk:hover { background: var(--hairline-2); }
.stage.clk:hover .num { color: var(--verify); }
.tile.clk { cursor: pointer; }
.tile.clk:hover { border-color: var(--verify); }

