// ============================================================
// Dashboard stats widget — Pipeline funnel + Stage-Volume matrix
// One data source drives everything: `periods`.
// Column order: [Loaded, Integrity, Verif I, Verif II, Audit I, Audit II, Processed, Total]
// To wire real data: set appsmith.model.periods from a query (same shape).
// ============================================================

var nf = new Intl.NumberFormat("en-US");

// Fallback demo data (matches the UBM Demo dashboard) — used until a query feeds model.periods
var DEMO_PERIODS = [
  { label: "Since Yesterday", v: [0, 0, 0, 0, 0, 0, 0, 0] },
  { label: "Last 7 Days",     v: [0, 0, 0, 0, 0, 0, 0, 0] },
  { label: "Last 31 Days",    v: [0, 0, 0, 0, 0, 0, 0, 0] },
  { label: "All-Time",        v: [0, 0, 0, 0, 0, 0, 0, 0] }
];

var STAGE_META = [
  { name: "Bills Loaded",         c: "var(--intake)" },
  { name: "Integrity Check",      c: "var(--review)" },
  { name: "Data Verification I",  c: "var(--verify)" },
  { name: "Data Verification II", c: "var(--verify)" },
  { name: "Data Audit I",         c: "var(--audit)"  },
  { name: "Data Audit II",        c: "var(--audit)"  },
  { name: "Processed",            c: "var(--done)"   }
];

var STAGE_KEYS = ["bill_loaded", "integrity_check", "data_verification_1", "data_verification_2", "data_audit_1", "data_audit_2", "processed", "all"];
var STAGE_LABELS = ["Bills Loaded", "Integrity Check", "Data Verification I", "Data Verification II", "Data Audit I", "Data Audit II", "Processed", "All bills"];

function getPeriods(model) {
  if (model && Array.isArray(model.periods) && model.periods.length) return model.periods;
  return DEMO_PERIODS;
}

function allTimeRow(periods) {
  for (var i = 0; i < periods.length; i++) {
    if (periods[i] && /all[\s-]?time/i.test(periods[i].label || "")) return periods[i];
  }
  return periods[periods.length - 1] || { v: [] };
}

function renderKpis(all) {
  var v = all.v || [];
  var total = Number(v[7]) || 0;
  var proc = Number(v[6]) || 0;
  var rate = total ? (proc / total) * 100 : 0;
  var el = document.getElementById("kpis");
  if (!el) return;
  el.innerHTML =
    tile("var(--brand)", "Total Bills", nf.format(total), "All-Time · click to view bills", null, { stage: "all", period: "All-Time", label: "All bills" }) +
    tile("var(--done)", "Processed", nf.format(proc), "All-Time · click to view bills", null, { stage: "processed", period: "All-Time", label: "Processed" }) +
    tile("var(--verify)", "Completion Rate", rate.toFixed(1) + "<small>%</small>", "Processed ÷ Total", rate);
}

function tile(accent, lab, val, meta, barPct, drill) {
  var bar = barPct === null ? "" :
    '<div class="barline"><i style="width:' + Math.max(0, Math.min(100, barPct)) + '%"></i></div>';
  var open = drill
    ? '<div class="tile clk" data-stage="' + drill.stage + '" data-period="' + drill.period + '" data-label="' + drill.label + '" style="--accent:' + accent + '">'
    : '<div class="tile" style="--accent:' + accent + '">';
  return open +
    '<div class="lab">' + lab + '</div>' +
    '<div class="val tnum">' + val + '</div>' +
    '<div class="meta">' + meta + '</div>' + bar + '</div>';
}

function renderFunnel(all) {
  var v = all.v || [];
  var stages = STAGE_META.map(function (m, i) { return { name: m.name, c: m.c, n: Number(v[i]) || 0, key: STAGE_KEYS[i] }; });
  var total = Number(v[7]) || 0;
  var max = Math.max.apply(null, stages.map(function (s) { return s.n; }).concat([1]));
  var el = document.getElementById("funnel");
  if (!el) return;
  el.innerHTML = stages.map(function (s) {
    var w = max ? (s.n / max) * 100 : 0;
    var share = total ? (s.n / total) * 100 : 0;
    return '<div class="stage clk ' + (s.n === 0 ? "empty" : "") + '" data-stage="' + s.key + '" data-period="All-Time" data-label="' + s.name + ' \u00b7 All-Time" style="--c:' + s.c + '">' +
      '<div class="name"><i></i>' + s.name + '</div>' +
      '<div class="track"><b style="width:' + w + '%"></b></div>' +
      '<div class="num tnum">' + nf.format(s.n) +
      '<small>' + share.toFixed(1) + '% of total</small></div></div>';
  }).join("");
}

function renderMatrix(periods) {
  var el = document.getElementById("matrix");
  if (!el) return;
  el.innerHTML = periods.map(function (r) {
    var isAll = /all[\s-]?time/i.test(r.label || "");
    var cells = (r.v || []).map(function (n, i) {
      n = Number(n) || 0;
      var isTotal = i === 7, isProc = i === 6;
      var cls = [n === 0 ? "zero" : "", isTotal ? "total col-div" : "", isProc ? "proc col-div" : ""].join(" ").trim();
      return '<td class="' + cls + ' clk" data-stage="' + STAGE_KEYS[i] + '" data-period="' + r.label + '" data-label="' + STAGE_LABELS[i] + ' \u00b7 ' + r.label + '"><span class="v tnum">' + nf.format(n) + "</span></td>";
    }).join("");
    return '<tr class="' + (isAll ? "alltime" : "") + '"><td class="rowlab">' + r.label + "</td>" + cells + "</tr>";
  }).join("");
}

function render(model) {
  var periods = getPeriods(model);
  var all = allTimeRow(periods);
  renderKpis(all);
  renderFunnel(all);
  renderMatrix(periods);
}

function fireDrill(stage, period, label) {
  appsmith.updateModel({ drill: { stage: stage, period: period, title: label } });
  appsmith.triggerEvent("onDrill");
}

appsmith.onReady(function () {
  render(appsmith.model);
  document.addEventListener("click", function (ev) {
    var el = ev.target && ev.target.closest ? ev.target.closest("[data-stage]") : null;
    if (!el) return;
    fireDrill(el.getAttribute("data-stage"), el.getAttribute("data-period"), el.getAttribute("data-label"));
  });
  appsmith.onModelChange(function (newModel) { render(newModel); });
});

