      return '<td class="' + cls + ' clk" data-stage="' + STAGE_KEYS[i] + '" data-period="' + r.label + '" data-label="' + STAGE_LABELS[i] + ' \u00b7 ' + r.label + '"><span class="v tnum">' + nf.format(n) + "</span></td>";
    }).join("");
    return '<tr class="' + (isAll ? "alltime" : "") + '"><td class="rowlab">' + r.label + "</td>" + cells + "</tr>";
  }).join("");
}

function render(model) {
  var periods = getPeriods(model);
  var all = allTimeRow(periods);
  renderKpis(all);
  renderFunnel(all);
  renderMatrix(periods);
}

function fireDrill(stage, period, label) {
  appsmith.updateModel({ drill: { stage: stage, period: period, title: label } });
  appsmith.triggerEvent("onDrill");
}

appsmith.onReady(function () {
  render(appsmith.model);
  document.addEventListener("click", function (ev) {
    var el = ev.target && ev.target.closest ? ev.target.closest("[data-stage]") : null;
    if (!el) return;
    fireDrill(el.getAttribute("data-stage"), el.getAttribute("data-period"), el.getAttribute("data-label"));
  });
  appsmith.onModelChange(function (newModel) { render(newModel); });
});
